def _attach_keyword_fallback(
    output: Path,
    question: str,
    result: dict[str, Any],
    metadata: dict[str, Any],
) -> dict[str, Any]:
    record_path = write_keyword_fallback_record(output, question, metadata)
    metadata = {**metadata, "record": str(record_path.resolve())}
    result = {**result, "keyword_fallback": metadata, "keyword_fallback_record": str(record_path.resolve())}
    retrieval_record = result.get("record")
    if isinstance(retrieval_record, str) and Path(retrieval_record).is_file():
        persisted = json_load(Path(retrieval_record))
        if isinstance(persisted, dict):
            persisted["keyword_fallback"] = metadata
            persisted["keyword_fallback_record"] = str(record_path.resolve())
            json_write(Path(retrieval_record), persisted)
    return result

def entity_lookup(output: Path, selector: str) -> dict[str, Any]:
    path = output / MACHINE_PATH
    connection = sqlite3.connect(f"file:{path.as_posix()}?mode=ro", uri=True)
    connection.row_factory = sqlite3.Row
    try:
        rows = connection.execute(
            "SELECT e.*,r.start_line,r.end_line,h.title AS human_title,h.page_file,h.display_mode FROM entities e JOIN source_ranges r USING(entity_id) LEFT JOIN human_projection h USING(entity_id) WHERE e.entity_id=? OR e.name=? COLLATE NOCASE OR e.qualified_name=? COLLATE NOCASE ORDER BY e.qualified_name LIMIT 20",
            (selector, selector, selector),
        ).fetchall()
    finally:
        connection.close()
    return {"schema_version": MACHINE_SCHEMA_VERSION, "status": "passed" if rows else "not-found", "selector": selector, "candidates": [dict(row) for row in rows]}

def neighbor_lookup(output: Path, selector: str, depth: int = 1, relation: str | None = None, limit: int = 50) -> dict[str, Any]:
    if depth < 1 or depth > 6:
        raise CkbError("neighbor depth must be in [1, 6]")
    found = entity_lookup(output, selector)
    if len(found["candidates"]) != 1:
        return {**found, "reason": "selector must match exactly one entity"}
    root_id = found["candidates"][0]["entity_id"]
    path = output / MACHINE_PATH
    connection = sqlite3.connect(f"file:{path.as_posix()}?mode=ro", uri=True)
    connection.row_factory = sqlite3.Row
    try:
        visited = {root_id}
        frontier = {root_id}
        rows: list[dict[str, Any]] = []
        for current_depth in range(1, depth + 1):
            next_frontier: set[str] = set()
            for entity_id in sorted(frontier):
                query = "SELECT * FROM relations WHERE (source_entity_id=? OR target_entity_id=?)"
                params: list[Any] = [entity_id, entity_id]
                if relation:
                    query += " AND relation=?"
                    params.append(relation)
                query += " ORDER BY relation_id"
                for row in connection.execute(query, params):
                    target = row["target_entity_id"] if row["source_entity_id"] == entity_id else row["source_entity_id"]
                    entity = connection.execute("SELECT name,qualified_name,source_path FROM entities WHERE entity_id=?", (target,)).fetchone()
                    rows.append({"depth": current_depth, "from": entity_id, "entity_id": target, "relation": row["relation"], "direction": "outgoing" if row["source_entity_id"] == entity_id else "incoming", **dict(entity)})
                    if target not in visited:
                        visited.add(target)
                        next_frontier.add(target)
                    if len(rows) >= limit:
                        break
                if len(rows) >= limit:
                    break
            frontier = next_frontier
            if not frontier or len(rows) >= limit:
                break
    finally:
        connection.close()
    return {"schema_version": MACHINE_SCHEMA_VERSION, "status": "passed", "selector": selector, "root_entity_id": root_id, "depth": depth, "relation": relation, "neighbors": rows}

def source_lookup(output: Path, selector: str, context_lines: int = 3) -> dict[str, Any]:
    found = entity_lookup(output, selector)
    if len(found["candidates"]) != 1:
        return {**found, "reason": "selector must match exactly one entity"}
    entity = found["candidates"][0]
    path = output / MACHINE_PATH
    connection = sqlite3.connect(f"file:{path.as_posix()}?mode=ro", uri=True)
    try:
        row = connection.execute("SELECT source_text FROM files WHERE path=?", (entity["source_path"],)).fetchone()
    finally:
        connection.close()
    if row is None:
        return {"schema_version": MACHINE_SCHEMA_VERSION, "status": "not-found", "selector": selector, "reason": "source file is absent from the fixed snapshot"}
    lines = row[0].splitlines()
    start = max(1, int(entity["start_line"]) - context_lines)
    end = min(len(lines), int(entity["end_line"]) + context_lines)
    excerpt = "\n".join(f"{index:>6}  {lines[index - 1]}" for index in range(start, end + 1))
    return {"schema_version": MACHINE_SCHEMA_VERSION, "status": "passed", "selector": selector, "entity_id": entity["entity_id"], "source_path": entity["source_path"], "start_line": start, "end_line": end, "excerpt": excerpt}

def sync_workspace_changes(output: Path) -> dict[str, Any]:
    path = output / MACHINE_PATH
    overlay = output / "workspace-meta/working-overlay.json"
    if not path.is_file() or not overlay.is_file():
        return {"schema_version": MACHINE_SCHEMA_VERSION, "status": "skipped", "reason": "machine database or working overlay is absent"}
    value = json_load(overlay)
    connection = sqlite3.connect(path)
    try:
        connection.execute("DELETE FROM workspace_changes")
        detail = json.dumps(value, ensure_ascii=False, sort_keys=True)
        for changed in value.get("changed_paths", []):
            connection.execute("INSERT INTO workspace_changes VALUES(?,?,?)", (changed, "changed", detail))
        for untracked in value.get("untracked_paths", []):
            connection.execute("INSERT INTO workspace_changes VALUES(?,?,?)", (untracked, "untracked", detail))
        connection.commit()
    finally:
        connection.close()
    return {"schema_version": MACHINE_SCHEMA_VERSION, "status": "passed", "changed": len(value.get("changed_paths", [])), "untracked": len(value.get("untracked_paths", []))}

def default_management_registry_path() -> Path:
    configured = os.environ.get(MANAGEMENT_REGISTRY_ENV)
    return Path(configured).expanduser() if configured else Path.home() / ".ckb" / "management-bindings.json"

def management_human_maintenance_prompt_contract(action: str | None = None) -> dict[str, Any]:
    """Read the shared immutable Prompt contract without adding manager state."""

    if action is None:
        document = human_maintenance_registry_document()
    else:
        document = {
            "schema_version": MANAGEMENT_SCHEMA_VERSION,
            "action": human_maintenance_action_document(action),
        }
    return {**document, "registry_sha256": human_maintenance_registry_sha256()}

def _path_key(path: Path | str) -> str:
    value = os.path.abspath(os.path.expanduser(str(path)))
    return os.path.normcase(os.path.normpath(value)).replace("\\", "/").rstrip("/")

def _empty_registry() -> dict[str, Any]:
    return {
        "schema_version": MANAGEMENT_SCHEMA_VERSION,
        "bindings": [],
        "tasks": [],
        "audit_log": [],
    }

def _read_registry(path: Path) -> dict[str, Any]:
    if not path.is_file():
        return _empty_registry()
    value = json_load(path)
    if not isinstance(value, dict):
        raise CkbError(f"management registry must be one JSON object: {path}")
    if value.get("schema_version") != MANAGEMENT_SCHEMA_VERSION:
        raise CkbError(f"unsupported management registry: {path}")
    for field in ("bindings", "tasks", "audit_log"):
        if not isinstance(value.get(field), list):
            raise CkbError(f"management registry field must be a list: {field}")
    return value

def _registry_lock(path: Path, timeout: float = 30.0) -> Iterator[None]:
    path.parent.mkdir(parents=True, exist_ok=True)
    lock = path.with_name(path.name + ".lock")
    deadline = time.monotonic() + timeout
    descriptor: int | None = None
    while descriptor is None:
        try:
            descriptor = os.open(lock, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
            os.write(descriptor, f"{os.getpid()}\n{time.time()}\n".encode("ascii"))
        except (FileExistsError, PermissionError):
            try:
                if time.time() - lock.stat().st_mtime > 60:
                    lock.unlink(missing_ok=True)
                    continue
            except FileNotFoundError:
                continue
            if time.monotonic() >= deadline:
                raise CkbError(f"management registry is busy: {path}")
            time.sleep(0.05)
    try:
        yield
    finally:
        if descriptor is not None:
            os.close(descriptor)
        lock.unlink(missing_ok=True)

def harness_capabilities(harness_id: str) -> dict[str, dict[str, Any]]:
    harness = harness_id.strip().casefold()
    if harness not in SUPPORTED_HARNESSES:
        return {
            "binding": _capability(True, "generic-cli"),
            "prompt_injection": _capability(False, "no-adapter"),
            "event_sync": _capability(False, "no-adapter"),
            "task_dispatch": _capability(False, "no-adapter"),
        }
    return {
        "binding": _capability(True, "manager-cli"),
        "prompt_injection": _capability(False, "manual-context"),
        "event_sync": _capability(True, "generic-json" if harness == "generic" else "automation-adapter"),
        "task_dispatch": _capability(True, "manager-cli"),
    }

def canonical_binding_input(payload: dict[str, Any]) -> tuple[dict[str, Any], list[str]]:
    if not isinstance(payload, dict):
        raise CkbError("management binding input must be one JSON object")
    if payload.get("schema_version") != MANAGEMENT_SCHEMA_VERSION:
        raise CkbError(f"management binding requires schema_version={MANAGEMENT_SCHEMA_VERSION}")
    allowed = set(binding_schema()["properties"])
    ignored = sorted(str(key) for key in payload if key not in allowed)
    value = {key: payload[key] for key in allowed if key in payload and key != "capabilities"}
    required = set(binding_schema()["required"])
    missing = sorted(field for field in required if not isinstance(value.get(field), (str, int)) or not str(value[field]).strip())
    if missing:
        raise CkbError(f"management binding input is missing required fields: {missing}")
    if int(value["schema_version"]) != MANAGEMENT_SCHEMA_VERSION:
        raise CkbError(f"management binding requires schema_version={MANAGEMENT_SCHEMA_VERSION}")
    for field in ("conversation_id", "harness_id"):
        text = str(value[field]).strip()
        if not _OPAQUE_ID.fullmatch(text):
            raise CkbError(f"management binding {field} must be bounded opaque text")
        value[field] = text
    value["harness_id"] = str(value["harness_id"]).casefold()
    policy = str(value.get("notification_policy", "none")).strip().casefold()
    if policy not in NOTIFICATION_POLICIES:
        raise CkbError(f"unsupported management notification policy: {policy}")
    value["notification_policy"] = policy
    for field in ("workspace_root", "repo_root", "knowledge_base"):
        value[field] = _normalized_path(str(value[field]))
    value["integration_branch"] = str(value["integration_branch"]).strip()
    value["capabilities"] = harness_capabilities(value["harness_id"])
    return value, ignored

def _privacy_errors(value: Any, location: str = "registry") -> list[str]:
    errors: list[str] = []
    if isinstance(value, dict):
        for key, child in value.items():
            lowered = str(key).casefold().replace("-", "_")
            if lowered in _FORBIDDEN_INPUT_FIELDS:
                errors.append(f"{location}: forbidden persisted field: {key}")
            errors.extend(_privacy_errors(child, f"{location}.{key}"))
    elif isinstance(value, list):
        for index, child in enumerate(value):
            errors.extend(_privacy_errors(child, f"{location}[{index}]"))
    return errors
